-- Midnight main campaign: "[DNT] Kill Credit: Arrive/Enter/Scout..." objectives have no mechanism on this server.
-- The retail QuestPOI area of the objective (midnight_poi_0data.lua, generated by tools/gen_poi_credit.py) is used as the trigger:
-- while the player has the quest and stands inside the circle, the kill credit is given (the core ignores it when the
-- objective is already done or not yet reachable because of sequencing, so retrying every few seconds is harmless).
if IS_WORLD_STATE or not MAP_Timer or not MIDNIGHT_POI then return end

local INCOMPLETE = 3
local last, enter = {}, {}

-- credits that simply mean "arrived on this map" (Travel to Quel'Danas etc.)
local MAP_CREDITS = {
    { q = 88719, c = 239653, map = 2858 },   -- A Voice from the Light: Travel to Quel'Danas
}

local function Tick()
    for _, p in ipairs(MAP_Players()) do
        if p:IsInWorld() then
            local mapId = p:GetMapId()
            local px, py = p:GetLocation()
            for _, m in ipairs(MAP_CREDITS) do
                if m.map == mapId then
                    local okm, stm = pcall(function() return p:GetQuestStatus(m.q) end)
                    if okm and stm == INCOMPLETE then pcall(function() p:KilledMonsterCredit(m.c) end) end
                end
            end
            for i, a in ipairs(MIDNIGHT_POI) do
                if a.map == mapId then
                    local dx, dy = px - a.x, py - a.y
                    if dx * dx + dy * dy <= a.r * a.r then
                        local ok, st = pcall(function() return p:GetQuestStatus(a.q) end)
                        if ok and st == INCOMPLETE then
                            local key = tostring(p:GetGUID()) .. ":" .. i
                            local now = os.time()
                            enter[key] = enter[key] or now
                            if now - enter[key] >= (a.dwell or 1) and (last[key] or 0) + 6 <= now then
                                last[key] = now
                                pcall(function() p:KilledMonsterCredit(a.c) end)
                            end
                        end
                    else
                        enter[tostring(p:GetGUID()) .. ":" .. i] = nil
                    end
                end
            end
        end
    end
end

MAP_Timer("midnight_poi_credit", function() pcall(Tick) end, 1500)
print("[midnight_poi_credit] loaded " .. #MIDNIGHT_POI .. " areas")
